// Benchmark fait main : illustre warmup + repetitions.
// En vrai, prefere l'outil JMH (Java Microbenchmark Harness), concu pour la JVM.
int warmup = 10_000;      // iterations de chauffe, resultats jetes
int mesures = 100_000;    // iterations reellement mesurees

// Phase de chauffe : on laisse le JIT compiler le code chaud
for (int i = 0; i < warmup; i++) {
    resultat = codeAMesurer();
}

// Phase de mesure : on enregistre chaque duree
long[] durees = new long[mesures];
for (int i = 0; i < mesures; i++) {
    long debut = System.nanoTime();
    resultat = codeAMesurer();
    durees[i] = System.nanoTime() - debut;
}

